contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        address expectedAsserter = address(c.optimisticAsserter());
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (msg.sender == expectedAsserter && !reverted && address(c).balance == beforeBalance) ||
            (msg.sender != expectedAsserter && reverted && address(c).balance == beforeBalance)
        );
    }

    receive() external payable {}
}

