contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData,
        bytes32 assertionId,
        address disputeCaller
    ) public {
        require(true);

        bool revertedRequestPrice;
        if (msg.sender != address(c.optimisticAsserter())) {
            try c.requestPrice(identifier, time, ancillaryData) {
                revertedRequestPrice = false;
            } catch {
                revertedRequestPrice = true;
            }
        } else {
            revertedRequestPrice = false;
        }

        bool revertedResolved;
        if (msg.sender != address(c.optimisticAsserter())) {
            try c.assertionResolvedCallback(assertionId, true) {
                revertedResolved = false;
            } catch {
                revertedResolved = true;
            }
        } else {
            revertedResolved = false;
        }

        bool revertedDisputed;
        if (msg.sender != address(c.optimisticAsserter())) {
            try c.assertionDisputedCallback(assertionId) {
                revertedDisputed = false;
            } catch {
                revertedDisputed = true;
            }
        } else {
            revertedDisputed = false;
        }

        assert(
            (msg.sender == address(c.optimisticAsserter())) ||
            (revertedRequestPrice && revertedResolved && revertedDisputed)
        );
    }
}

