contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        // Read-only call: verify the optimistic asserter address is what the test contract was given.
        // (No state change, so it may be used in require/assert.)
        require(optimisticAsserterAddress() == address(c.optimisticAsserter()), "unexpected optimisticAsserter");

        // Make the deciding call: requestPrice, which should revert because msg.sender is this test contract,
        // not the optimistic asserter address.
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: requestPrice must revert for any non-optimistic-asserter caller.
        // Also, no PriceRequestAdded event can have been emitted because the call reverted.
        // The event assertion is encoded indirectly: if it had not reverted, the state would have
        // been mutated and the reverted flag would be false; the contract's event emission is
        // only possible on success, so the reverted flag alone is the observable invariant here.
        assert(reverted);
    }

    function optimisticAsserterAddress() internal view returns (address) {
        // Helper view to avoid repeating the external call inside the assert/require.
        return address(c.optimisticAsserter());
    }

    receive() external payable {}
}

