contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        c.requestPrice(identifier, time, ancillaryData);
        int256 price = c.getPrice(identifier, time, ancillaryData);
        OptimisticAsserterInterface.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);
        assert(allowed && price == int256(0) && policy.blockAssertion == false && policy.arbitrateViaEscalationManager == false && policy.discardOracle == false && policy.validateDisputers == false);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 assertionId, address disputeCaller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);
        (bool ok1, ) = address(c).call(abi.encodeWithSelector(c.requestPrice.selector, identifier, time, ancillaryData));
        int256 price = c.getPrice(identifier, time, ancillaryData);
        (bool ok2, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(c.getAssertionPolicy.selector, assertionId));
        require(ok2, "getAssertionPolicy failed");
        (bool blockAssertion,
         bool arbitrateViaEscalationManager,
         bool discardOracle,
         bool validateDisputers) = abi.decode(ret, (bool, bool, bool, bool));
        assert(allowed == true && ok1 == false && price == int256(0) && blockAssertion == false && arbitrateViaEscalationManager == false && discardOracle == false && validateDisputers == false);
    }

    receive() external payable {}
}

