    }

    function run(address caller, bytes32 assertionId0, bool truth0, bytes32 assertionId1, bool truth1) public {
        // The optimistic asserter address is read from a public immutable getter, so this is safe.
        address oa = c.optimisticAsserter();

        bool revertedByAsserter;
        if (caller == oa) {
            c.assertionResolvedCallback(assertionId0, truth0);
            revertedByAsserter = false;
        } else {
            try c.assertionResolvedCallback(assertionId0, truth0) {
                revertedByAsserter = false;
            } catch {
                revertedByAsserter = true;
            }
        }

        bool revertedByNonAsserter;
        if (caller != oa) {
            try c.assertionResolvedCallback(assertionId1, truth1) {
                revertedByNonAsserter = false;
            } catch {
                revertedByNonAsserter = true;
            }
        } else {
            c.assertionResolvedCallback(assertionId1, truth1);
            revertedByNonAsserter = false;
        }

        // General rule: only the optimistic asserter may call assertionResolvedCallback and it must not revert.
        assert((caller == oa) ? (!revertedByAsserter && !revertedByNonAsserter) : (revertedByAsserter && revertedByNonAsserter));
    }

    receive() external payable {}
}

