contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // msg.sender here is the test contract, which deployed c, so c.optimisticAsserter() == address(this).
        // A call from this contract must be allowed and must emit PriceRequestAdded.
        bool emitted;
        try c.requestPrice(identifier, time, ancillaryData) {
            emitted = true;
        } catch {
            emitted = false;
        }

        // General rule: since the caller is the optimistic asserter, requestPrice must succeed
        // (not revert) and must therefore have executed its emission path.
        assert(emitted);
    }

    receive() external payable {}
}

